with kept_keys as (select id from departments except select id from departments where budget <= 2252000), kept_rows as (select s.* from departments s inner join kept_keys k on s.id = k.id) select case when budget >= 3694000 then 'HIGH' else 'LOW' end as budget_tier, location, count(case when location = 'Tokyo' then 1 end) as tokyo_count, stddev_samp(budget) as budget_stddev from kept_rows group by case when budget >= 3694000 then 'HIGH' else 'LOW' end, location having budget_stddev > 0;
